var constellation = [];
var n; //number of stars in constellation
var d; //distance between two stars

function setup() {
  createCanvas(500, 500);
  pixelDensity(1); // Set 1 because it's too slow on firefox
  //pixelDensity(displayDensity());
  n = 200;

  for (var i = 0; i < n; i++) {
    constellation.push(new star());
  }
  strokeWeight(0.75);
  stroke('#00FFaF');
}

//links all dots which are not farther than width/8
function draw() {

  background('#000020');

  for (var i = 0; i < n; i++) {
    constellation[i].update();
    for (var j = 0; j < n; j++) {
        if (i > j) { //to check two points only once
        d = constellation[i].loc.dist(constellation[j].loc); // distance 
          if (d <= width / 8) { // if d is less than width/8 px, we draw a line between two stars
          line(constellation[i].loc.x, constellation[i].loc.y, constellation[j].loc.x, constellation[j].loc.y)
          }
        }
     }
   }

}

function star() {

  this.a = random (5*TAU); // alpha; "5*TAU" => render will be more homogeneous; TAU = 2*pi
  this.r = random (width*0.4, width*0.25); // radius; first position will look like a donut
  this.loc = createVector (width/2 + sin(this.a)*this.r, height/2 + cos(this.a)*this.r); // x & y of the star
  this.speed = createVector(); //
  this.speed = p5.Vector.random2D(); //
  //this.speed.random2D();
  this.bam = createVector(); // ?
  this.m; // ?


  this.update = function() {
      this.bam = p5.Vector.random2D(); // movement of the star will be a bit erractic
      //this.bam.random2D();
      this.bam.mult(0.45);
      this.speed.add(this.bam);
      // speed is done according to distance between loc and the mouse
      this.m = map (dist (this.loc.x, this.loc.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))), 0, width, 8, 0.05);
      //this.m = constrain (map (dist (this.loc.x, this.loc.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))), 0, width, 8, 0.05), 0.05, 8); // constrain => avoid returning "not a number"
      this.speed.normalize().mult(this.m);

      /* // No collision detection, instead loc is out of bound
      // it reappears on the opposite side:
      if (dist (this.loc.x, this.loc.y, width/2, height/2) > (width/2) * 0.98) {
        if (this.loc.x < width/2) {
          this.loc.x = width - this.loc.x - 4; // "-4" => avoid blinking stuff
        } else if (this.loc.x > width/2) {
          this.loc.x = width - this.loc.x + 4; // "+4"  => avoid blinking stuff
        }
        if (this.loc.y < height/2) {
          this.loc.y = width - this.loc.y;
        } else if (this.loc.x > height/2) {
          this.loc.y = width - this.loc.y;
        }
      } */
      if (dist (this.loc.x, this.loc.y, width/2, height/2) > (width/2) * 0.98) {
        this.loc.x = width - this.loc.x;
        this.loc.y = width - this.loc.y;
      }
      this.loc = this.loc.add(this.speed);
    } // End of update()
} // End of class

